<?php
require 'config.php'; require_login();
$q=trim((string)($_GET['q']??'')); $status=(string)($_GET['status']??'all'); if(!in_array($status,['all','completed','failed','running'],true))$status='all';
$page=max(1,(int)($_GET['page']??1)); $per=10; $where=' WHERE 1=1'; $args=[];
if($q!==''){$where.=' AND (s.name LIKE ? OR s.start_url LIKE ? OR CAST(r.id AS CHAR) LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like);} if($status!=='all'){$where.=' AND r.status=?';$args[]=$status;}
$st=$pdo->prepare('SELECT COUNT(*) FROM scan_runs r JOIN sites s ON s.id=r.site_id'.$where);$st->execute($args);$total=(int)$st->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);
$st=$pdo->prepare('SELECT r.*,s.name,s.start_url FROM scan_runs r JOIN sites s ON s.id=r.site_id'.$where.' ORDER BY r.id DESC LIMIT '.$per.' OFFSET '.(($page-1)*$per));$st->execute($args);$runs=$st->fetchAll();
layout_start('Lịch sử quét'); ?>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4"><div><div class="small-label mb-2">SCAN ARCHIVE</div><h1 class="h3 page-title mb-1">Lịch sử quét</h1><p class="muted mb-0">Tìm kiếm, lọc và phân trang các phiên đã lưu.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-primary" href="compare.php">So sánh phiên</a><?php if((current_user()['role']??'')==='admin'):?><a class="btn btn-primary" href="index.php">＋ Tạo phiên quét</a><?php endif;?></div></div>
<div class="card p-3 p-md-4"><form method="get" class="row g-2 mb-3"><div class="col-md-7"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Tìm tên website, URL hoặc mã phiên"></div><div class="col-md-3"><select class="form-select" name="status"><option value="all">Mọi trạng thái</option><?php foreach(['completed'=>'Hoàn tất','failed'=>'Thất bại','running'=>'Đang chạy'] as $k=>$v):?><option value="<?=$k?>" <?=$status===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-2 d-grid"><button class="btn btn-outline-primary">Lọc kết quả</button></div></form>
<div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Phiên</th><th>Website</th><th>Bắt đầu</th><th>Trạng thái</th><th>Trang</th><th>Liên kết</th><th>Lỗi</th><th></th></tr></thead><tbody><?php if(!$runs):?><tr><td colspan="8" class="text-center py-5 muted">Không có phiên phù hợp.</td></tr><?php endif;foreach($runs as $r):?><tr><td class="fw-semibold">#<?=e($r['id'])?></td><td><strong><?=e($r['name'])?></strong><div class="small muted wrap-url"><?=e($r['start_url'])?></div></td><td><?=e($r['started_at'])?></td><td><span class="badge text-bg-<?=($r['status']==='completed'?'success':($r['status']==='failed'?'danger':'secondary'))?>"><?=e($r['status'])?></span></td><td><?=number_format((int)$r['total_pages_crawled'])?></td><td><?=number_format((int)$r['total_links_found'])?></td><td><span class="badge text-bg-<?=((int)$r['total_errors']>0?'danger':'success')?>"><?=number_format((int)$r['total_errors'])?></span></td><td><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="report.php?run_id=<?=(int)$r['id']?>">Báo cáo</a><a class="btn btn-sm btn-outline-success" href="export.php?run_id=<?=(int)$r['id']?>">CSV</a></div></td></tr><?php endforeach;?></tbody></table></div>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mt-3"><span class="small muted">Tổng <?=number_format($total)?> phiên · Trang <?=$page?>/<?=$pages?></span><nav aria-label="Phân trang"><ul class="pagination pagination-sm mb-0"><?php for($i=1;$i<=$pages;$i++):?><li class="page-item <?=$i===$page?'active':''?>"><a class="page-link" href="?q=<?=urlencode($q)?>&status=<?=urlencode($status)?>&page=<?=$i?>"><?=$i?></a></li><?php endfor;?></ul></nav></div></div><?php layout_end(); ?>
